  // Local response and explicit constraint proxies are identical to engine.js.
  const feature=o=>{const w=o.wob/100,r=o.rpm/120,q=o.flow/26,h=o.ucs/60;return[w,r,q,h,w*w,r*r,q*q,w*r,w*h,q*h];};
